"""Output parser for vs-contrastive-scoring."""

import re
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
# Only reach for the repo checkout when mlsbench is genuinely absent.
# Under Harbor this parser is exec'd from /tmp/mlsbench-verifier.XXXXXX/meta/,
# so a __file__-derived root is /tmp and this would put an agent-writable
# directory at the front of the verifier's sys.path.
try:  # noqa: E402
    import mlsbench  # noqa: F401
except ModuleNotFoundError:  # pragma: no cover - native checkout, no install
    sys.path.insert(0, str(PROJECT_ROOT / "src"))

from mlsbench.agent.parsers import OutputParser, ParseResult


class Parser(OutputParser):
    """Parse virtual screening training and evaluation output."""

    def parse(self, cmd_label: str, raw_output: str) -> ParseResult:
        feedback_parts = []
        metrics = {}

        if cmd_label == "train":
            # --- TRAIN_METRICS ---
            train_lines = [
                l.strip()
                for l in raw_output.splitlines()
                if l.strip().startswith("TRAIN_METRICS")
            ]
            if train_lines:
                feedback_parts.append(
                    f"Training progress:\n" + "\n".join(train_lines[-10:])
                )
            # Look for validation BEDROC
            for line in raw_output.splitlines():
                m = re.search(r"valid_bedroc\s*[=:]\s*([\d.]+)", line)
                if m:
                    val = float(m.group(1))
                    feedback_parts.append(f"valid_bedroc: {val:.4f}")

        else:
            # --- Evaluation metrics: the verifier-only scorer's line ---
            # TEST_METRICS auc_mean=.. bedroc_mean=.. ef005_mean=.. ef01_mean=..
            #              ef02_mean=.. ef05_mean=.. n_targets=..
            # (EF at 0.5 / 1 / 2 / 5 %); `TEST_METRICS status=INVALID` -> nothing.
            for line in raw_output.splitlines():
                line = line.strip()
                if line.startswith("TEST_METRICS"):
                    for match in re.finditer(r"(\w+)=([\d.eE+-]+)", line):
                        key, val = match.group(1), float(match.group(2))
                        metric_key = f"{key}_{cmd_label}"
                        metrics[metric_key] = val
                        feedback_parts.append(f"{metric_key}: {val:.6f}")

        if not feedback_parts:
            feedback_parts.append(raw_output[-3000:])

        return ParseResult(
            feedback="\n".join(feedback_parts),
            metrics=metrics,
        )
